export const WR_METRIC = Object.fromEntries(WR_METRICS.map(m => [m.key, m]));
export const wrSeries = months => { const rows = months.map(ym => ({ ym, S: wrScorecard(period(ym)) })), c = new Map(rows.map(r => [r.ym, r.S])); rows.lookup = ym => c.get(ym) || c.set(ym, wrScorecard(period(ym))).get(ym); return rows; };
